; Platform class capabilities
; ============================================================

ntc_rg573_e:
			IF ($ < 58624) && (ntc_rg574_e - ntc_rg574 + $ > 47616)	; fwdref-ok
			ds 58624 - $		; Option Memory Reserved #BA00-#E4FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg574_e - ntc_rg574 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg574:
;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			jr z, ntc_bs_ok		; (the stack just under them: CP/M's ntc_cpmstack = their start)
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "GURU 001", 0

ntc_rg574_e:
			IF ($ < 58624) && (ntc_rg575_e - ntc_rg575 + $ > 47616)	; fwdref-ok
			ds 58624 - $		; Option Memory Reserved #BA00-#E4FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg575_e - ntc_rg575 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg575:
;## ntc_plat_data
ntc_curx:		db 0			; cursor column (0 based)
ntc_cury:		db 0			; cursor row (0 based)
ntc_smode:		db 1			; screen mode (0, 1: 40 columns, 2: 80)
ntc_sinit:		db 0			; 1 once the tilemap is set up
ntc_scols:		db 40			; columns
ntc_wrapped:	db 0			; 1 = the last character wrapped to the next line
ntc_klink:		dw 0			; return for ntc_plat_getkey
ntc_kidx:		db 0			; key index found by the scan
ntc_kcur:		ds 8			; the 8 half rows this scan (0 = pressed)
ntc_kprev:		db #FF, #FF, #FF, #FF, #FF, #FF, #FF, #FF
ntc_irqset:		db 0			; 1 = our interrupt handler is at #38
ntc_irqold:		ds 3			; the 3 bytes it replaced
ntc_irqhl:		dw 0			; handler scratch
ntc_irqv:		dw 0			; interrupt classes' counting (ntc_isl_tick), 0 = none
ntc_zxvs:		db 0			; 1: this interrupt is a frame's first (line 0 passed: to ntc_isl_tick in C)
ntc_zxline:		dw 0			; the raster line the line interrupt is set to
ntc_zxsel:		db 0			; the NextReg selected (#243B) by code interrupts can get into: the
								; handler selects it again after its own (store it, then select)
ntc_zxl2:		db 0			; 1 = Layer 2 is on (Graphics); Mode turns it off
ZXN_MAP			equ #E000		; the tilemap (bank 5 + #2000: NextReg #6E = #20)
ZXN_TILES		equ #EC00		; its characters (bank 5 + #2C00: NextReg #6F = #2C)
ZXN_ROWS		equ 32
ZXN_PAPER		equ #02			; RRRGGGBB: blue
ZXN_INK			equ #FC			; yellow

ntc_rg575_e:
			IF ($ < 58624) && (ntc_rg576_e - ntc_rg576 + $ > 47616)	; fwdref-ok
			ds 58624 - $		; Option Memory Reserved #BA00-#E4FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg576_e - ntc_rg576 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg576:
;## ntc_plat_screen ntc_plat_data ntc_font ntc_data ntc_plat_scroll @shared
; ------------------------------------------------------------
; ntc_plat_putc - A = character 32-126 (others print as ?), draw it
; ------------------------------------------------------------
ntc_plat_putc:
			cp 32
			jr c, ntc_pc_bad
			cp 127
			jr c, ntc_zx_put
ntc_pc_bad:
			ld a, '?'
			jr ntc_zx_put

; ------------------------------------------------------------
; ntc_plat_putglyph - DE = an 8 byte glyph in ntc_font (ZOSCII text): that
; character at the cursor, the cursor on (a glyph not in ntc_font: ?)
; ------------------------------------------------------------
ntc_plat_putglyph:
			ld hl, -ntc_font
			add hl, de				; HL = the glyph's offset: 0 .. 95 * 8 - 1
			ld a, h
			cp (95 * 8) / 256
			jr c, ntc_pg_in
			jr nz, ntc_pc_bad
			ld a, l
			cp (95 * 8) & 255
			jr nc, ntc_pc_bad
ntc_pg_in:
			srl h
			rr l
			srl h
			rr l
			srl h
			rr l
			ld a, l
			add a, 32
			; fall into ntc_zx_put

; A = a character code: into the tilemap at the cursor (its tile), the cursor on
ntc_zx_put:
			ld c, a
			ld a, (ntc_cury)		; HL = ZXN_MAP + row * columns + column
			ld l, a
			ld h, 0
			add hl, hl
			add hl, hl
			add hl, hl
			ld d, h
			ld e, l
			add hl, hl
			add hl, hl
			add hl, de				; row * 40
			ld a, (ntc_scols)
			cp 80
			jr nz, $+3
			add hl, hl				; row * 80
			ld a, (ntc_curx)
			ld e, a
			ld d, ZXN_MAP / 256		; (ZXN_MAP's low byte is 0)
			add hl, de
			ld (hl), c
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			ld (ntc_curx), a
			cp b
			jr z, ntc_pg_wrap
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_pg_wrap:
			ld a, 1				; wrapped: a new line straight after does nothing
			ld (ntc_wrapped), a
			jr ntc_nl_do

; ------------------------------------------------------------
; ntc_plat_newline - column 0, next row, scroll at the bottom. Straight
; after a wrap at the last column it does nothing (as the firmware does)
; ------------------------------------------------------------
ntc_plat_newline:
			ld a, (ntc_wrapped)
			or a
			jr z, ntc_nl_do
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_nl_do:
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp ZXN_ROWS
			jp nc, ntc_plat_scroll
			ld (ntc_cury), a
			jp (ix)

ntc_rg576_e:
			IF ($ < 58624) && (ntc_rg577_e - ntc_rg577 + $ > 47616)	; fwdref-ok
			ds 58624 - $		; Option Memory Reserved #BA00-#E4FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg577_e - ntc_rg577 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg577:
;## ntc_plat_scroll ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_plat_scroll - move rows 1-31 up one, clear row 31
; ------------------------------------------------------------
ntc_plat_scroll:
			ld a, ZXN_ROWS - 1
			ld (ntc_cury), a
			ld a, (ntc_scols)
			ld c, a
			ld b, 0					; BC = a row
			ld hl, ZXN_MAP
			add hl, bc
			ld de, ZXN_MAP
			cp 80
			ld bc, (ZXN_ROWS - 1) * 40
			jr nz, ntc_sc_40
			ld bc, (ZXN_ROWS - 1) * 80
ntc_sc_40:
			ldir					; DE = the last row
			ld h, d
			ld l, e
			ld (hl), ' '
			inc de
			ld c, a
			dec c
			ld b, 0
			ldir
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_cls - the whole tilemap spaces, cursor home
; ------------------------------------------------------------
ntc_plat_cls:
			ld hl, ZXN_MAP
			ld de, ZXN_MAP + 1
			ld bc, ZXN_ROWS * 80 - 1
			ld (hl), ' '
			ldir
			xor a
			ld (ntc_wrapped), a
			ld (ntc_curx), a
			ld (ntc_cury), a
			jp (ix)

ntc_rg577_e:
			IF ($ < 58624) && (ntc_rg578_e - ntc_rg578 + $ > 47616)	; fwdref-ok
			ds 58624 - $		; Option Memory Reserved #BA00-#E4FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg578_e - ntc_rg578 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg578:
;## ntc_plat_frame ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_plat_frame - wait for the end of the display (raster line 192: the
; bottom border starts). Normal mode: interrupts in while waiting
; ------------------------------------------------------------
ntc_plat_frame:
			ld (ntc_klink), ix		; (ntc_klink: the return - IX runs ntc_fr_line)
			ld a, (ntc_nmode)
			or a
			jr z, ntc_fr_go
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
ntc_fr_go:
			ld bc, #243B
ntc_fr_out:						; first out of lines 192 and on (the border, the sync)
			ld ix, ntc_fr_out2
			jr ntc_fr_line
ntc_fr_out2:
			jr nz, ntc_fr_out
ntc_fr_in:						; then wait for line 192
			ld ix, ntc_fr_in2
			jr ntc_fr_line
ntc_fr_in2:
			jr z, ntc_fr_in
			jr ntc_fr_at
; the raster line (NextReg #1E: its bit 8, #1F: bits 0-7), its two halves read
; again until bit 8 is the same both times (line 255 to 256 between them reads
; as 0): NZ = line 192 or more. Back to IX; keeps BC (#243B)
ntc_fr_line:
			ld a, #1E
			ld (ntc_zxsel), a		; (interrupts are in: the handler selects it again)
			out (c), a
			inc b
			in d, (c)
			dec b
			ld a, #1F
			ld (ntc_zxsel), a
			out (c), a
			inc b
			in e, (c)
			dec b
			ld a, #1E
			ld (ntc_zxsel), a
			out (c), a
			inc b
			in a, (c)
			dec b
			cp d
			jr nz, ntc_fr_line
			ld d, a
		IF NTC_ZXIRQ					; (the interrupt handler is in the program: normal mode)
			ld a, (ntc_irqset)		; the line interrupt's chain: a pulse that came while interrupts
			or a					; were off was lost - the wait here is where a program with long
			jr z, ntc_fr_lok		; stretches of them lets interrupts in, so see that the raster has
			ld a, d					; not passed the line set without its interrupt (the same line in
			and 1					; the same stretch every frame: Frame paces a program to the
			ld h, a					; frame, so a lost one would stay lost): then the handler is
			ld l, e					; called, to count the ticks missed and set the line ahead
			push de
			ex de, hl
			ld hl, (ntc_zxline)
			or a
			sbc hl, de				; the line set - now (mod 312): 0-56 = ahead, its pulse comes (the
			jr nc, ntc_fr_l1		; chain sets the next line 52 on at most); more = passed, lost
			ld de, 312
			add hl, de
ntc_fr_l1:
			ld de, -57
			add hl, de
			jr nc, ntc_fr_l2
			di
			call ntc_irq			; (ends with ei: as its interrupt would)
ntc_fr_l2:
			pop de
			ld bc, #243B
ntc_fr_lok:
		ENDIF
			ld a, d
			rra
			jr c, ntc_fr_lnz		; 256 and on
			ld a, e
			cp 192
			ccf
			sbc a, a				; #FF: 192-255, 0: below
			jp (ix)
ntc_fr_lnz:
			or 1
			jp (ix)
ntc_fr_at:
			di
			ld a, (ntc_nmode)
			or a
			jr z, ntc_fr_done
			ld sp, (ntc_ip)
ntc_fr_done:
			ld ix, (ntc_klink)
			jp (ix)

ntc_rg578_e:
			IF ($ < 58624) && (ntc_rg579_e - ntc_rg579 + $ > 47616)	; fwdref-ok
			ds 58624 - $		; Option Memory Reserved #BA00-#E4FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg579_e - ntc_rg579 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg579:
;## ntc_plat_exit ntc_plat_data
; ------------------------------------------------------------
; ntc_plat_exit - the end: interrupts off, a soft reset (NextReg 2 bit 0) -
; back to NextZXOS (a NEX file has no caller to return to)
; ------------------------------------------------------------
ntc_plat_exit:
			di
			ld bc, #243B
			ld a, #02
			out (c), a
			inc b
			ld a, 1
			out (c), a
ntc_ex_wait:
			jr ntc_ex_wait

ntc_rg579_e:
			IF ($ < 58624) && (ntc_rg580_e - ntc_rg580 + $ > 47616)	; fwdref-ok
			ds 58624 - $		; Option Memory Reserved #BA00-#E4FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg580_e - ntc_rg580 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg580:
;## ntc_plat_memtop
; ntc_plat_memtop - HL = the first byte the program's arrays and the Memory class's heap in
; main memory must not use. ZXN_MEMTOP (the compiler's): #BA00 with the FileSystem or Loader
; class (their DOS area #BA00-#BDFF, then the stack to #C000), #BE00 without (20261118-1). A
; program that runs on over the stack has its arrays in #C000-#FFFF, where the build has
; already checked them against what is there: the top is then #FD00 (the start-up stub).
; (20261118-1: it was #BA00 always, so such a program stopped at its start with GURU 001.)
; Called on the real stack (call / ret).
ntc_plat_memtop:
			IF ntc_free > #C000		; fwdref-ok
			ld hl, #FD00
			ELSE
			ld hl, ZXN_MEMTOP
			ENDIF
			ret

ntc_rg580_e:
			IF ($ < 58624) && (ntc_rg581_e - ntc_rg581 + $ > 47616)	; fwdref-ok
			ds 58624 - $		; Option Memory Reserved #BA00-#E4FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg581_e - ntc_rg581 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg581:
;## ntc_plat_ld ntc_plat_data @shared
; ------------------------------------------------------------
; Loader.Load (20261116-10): a file from the folder that was current when the program was
; run, on the default drive ("*") - and nothing else of FileSystem: F_STAT (its size),
; F_OPEN, F_READ a chunk at a time, F_CLOSE. The DOS call is FileSystem's: rst 8 with ROM 3
; paged in, from a trampoline copied once to #BA00 (entered by call, left by ret here). The
; folder is left as it is. ld_go: the method's parameters are in ld_nm / ld_ad / ld_mx,
; the result's address in ld_rs
; ------------------------------------------------------------
LD_T		equ #BA00		; the trampoline's copy
LD_NAME		equ #BC00		; the name, ASCIIZ, as the DOS reads it
LD_STAT		equ #BC40		; F_STAT's 11 bytes: the size is the last 4
LD_DATA		equ #BC80		; file data, a chunk
LD_CHUNK	equ 384
ld_go:
			ld (ld_tsp), sp
			ld sp, (ntc_csp)        ; the real stack: call / ret from here
			call ld_load
			ex de, hl
			ld hl, (ld_rs)
			ld (hl), e
			inc hl
			ld (hl), d
			ld sp, (ld_tsp)
			ret
ld_nm:		dw 0
ld_ad:		dw 0
ld_mx:		dw 0
ld_rs:		dw 0
ld_tsp:		dw 0
ld_left:		dw 0
ld_h:		db 0
ld_rdy:		db 0
; ld_load - HL = the length, or a status
ld_load:
			ld a, (ld_rdy)
			or a
			jr nz, ld_name
			ld hl, ld_tramp
			ld de, LD_T
			ld bc, ld_trampe - ld_tramp
			ldir                    ; the trampoline into #BA00, once
			ld a, 1
			ld (ld_rdy), a
ld_name:
			ld hl, (ld_nm)          ; the name to LD_NAME, ASCIIZ: 1 to 62 characters
			ld de, LD_NAME
			ld b, 63
			ld a, (hl)
			or a
			jr z, ld_badname
ld_nmlp:
			ld a, (hl)
			ld (de), a
			or a
			jr z, ld_stat
			inc hl
			inc de
			djnz ld_nmlp
ld_badname:
			ld hl, -4               ; BadName
			ret
ld_stat:
			ld a, #AC               ; F_STAT: A the drive ("*": the default), the name, DE 11 bytes
			ld hl, LD_NAME
			ld de, LD_STAT
			call ld_dos
			ld hl, -2               ; NotFound
			ret c
			ld hl, (LD_STAT + 9)
			ld a, h
			or l
			jr nz, ld_toobig        ; 64K or more
			ld de, (LD_STAT + 7)    ; its length
			ld hl, (ld_mx)
			or a
			sbc hl, de
			jr nc, ld_open
ld_toobig:
			ld hl, -8               ; TooBig
			ret
ld_open:
			ld (ld_left), de
			ld a, #9A               ; F_OPEN, B = 1: read, the file must be there
			ld hl, LD_NAME
			ld bc, #0100
			call ld_dos
			ld hl, -2
			ret c
			ld (ld_h), a
ld_chunk:
			ld hl, (ld_left)
			ld a, h
			or l
			jr z, ld_close
			ld de, LD_CHUNK
			or a
			sbc hl, de
			jr c, ld_last
			ld b, d
			ld c, e                 ; a whole chunk
			jr ld_read
ld_last:
			ld bc, (ld_left)
ld_read:
			push bc
			ld a, #9D               ; F_READ: A the handle, BC bytes, to LD_DATA
			ld hl, LD_DATA
			call ld_dosh
			pop de                  ; DE = asked for, BC = read
			jr c, ld_failed
			ld a, b
			or c
			jr z, ld_close          ; (shorter than its size said)
			push de
			push bc
			ld hl, LD_DATA
			ld de, (ld_ad)
			ldir
			ld (ld_ad), de
			pop bc
			ld hl, (ld_left)
			or a
			sbc hl, bc
			ld (ld_left), hl
			pop hl
			or a
			sbc hl, bc
			jr z, ld_chunk          ; all it asked for: more
ld_close:
			ld a, #9B               ; F_CLOSE
			call ld_dosh
			ld de, (ld_left)        ; the length: its size less what never came
			ld hl, (LD_STAT + 7)
			or a
			sbc hl, de
			ret
ld_failed:
			ld a, #9B
			call ld_dosh
			ld hl, -9               ; Failed
			ret
; ld_dosh - a call on the open file: A = the hook, the handle in A for the DOS
; ld_dos  - a call by name: A = the hook, "*" (the default drive) in A for the DOS
;   HL = the pointer (HL and IX), BC, DE as the hook wants. Carry = an error; A, BC back
ld_dosh:
			ld (LD_T + (ld_hk - ld_tramp)), a
			ld a, (ld_h)
			jr ld_dos2
ld_dos:
			ld (LD_T + (ld_hk - ld_tramp)), a
			ld a, "*"
ld_dos2:
			ld (LD_T + (ld_a - ld_tramp)), a
			ld (LD_T + (ld_bc - ld_tramp)), bc
			ld (LD_T + (ld_de - ld_tramp)), de
			ld (LD_T + (ld_ix - ld_tramp)), hl
			ld (LD_T + (ld_l - ld_tramp)), hl
			call LD_T
			ld bc, (LD_T + (ld_bc - ld_tramp))
			ld a, (LD_T + (ld_cy - ld_tramp))
			rra                     ; carry = the DOS's
			ld a, (LD_T + (ld_a - ld_tramp))
			ret
; ---- the trampoline (copied to #BA00; FileSystem's, entered by call, left by ret; the system
; variables' copy at #BAB0, its stack to #BC00)
ld_tramp:
			ld (#BA00 + (ld_sp - ld_tramp)), sp
			ld sp, #BC00            ; own stack: #BB30-#BBFF
			ld hl, #5C00            ; the ROM's system variables' area kept (an interrupt during the call
			ld de, #BAB0            ; runs ROM 3's handler, which writes there): 124 bytes to #BAB0-#BB2B (the trampoline is 164 bytes: to #BAA3)
			ld bc, 124
			ldir
			ld bc, #243B            ; MMU 0, 1 read (NextReg #50, #51) and set to 255 (ROM)
			ld a, #50
			out (c), a
			inc b
			in a, (c)
			ld (#BA00 + (ld_m0 - ld_tramp)), a
			dec b
			ld a, #51
			out (c), a
			inc b
			in a, (c)
			ld (#BA00 + (ld_m1 - ld_tramp)), a
			dec b
			ld a, #50
			out (c), a
			inc b
			ld a, #FF
			out (c), a
			dec b
			ld a, #51
			out (c), a
			inc b
			ld a, #FF
			out (c), a
			dec b
			ld a, #8E               ; ROM 3, slots 6-7 kept
			out (c), a
			inc b
			ld a, #03
			out (c), a
			ld bc, (#BA00 + (ld_bc - ld_tramp))
			ld de, (#BA00 + (ld_de - ld_tramp))
			ld ix, (#BA00 + (ld_ix - ld_tramp))
			ld hl, (#BA00 + (ld_l - ld_tramp))  ; HL: the name too, or F_SEEK's mode in L
			ld a, (#BA00 + (ld_a - ld_tramp))
			rst 8
ld_hk:		db 0
			ld (#BA00 + (ld_bc - ld_tramp)), bc
			ld (#BA00 + (ld_de - ld_tramp)), de
			ld (#BA00 + (ld_a - ld_tramp)), a
			ld a, 0
			adc a, a                ; 1 = carry: an error
			ld (#BA00 + (ld_cy - ld_tramp)), a
			ld bc, #243B
			ld a, #8E               ; ROM 0 again (20261110-2: the NEX stub leaves NextZXOS's DivMMC entry points, which
			out (c), a              ; trap rst 8 and #0038 whenever ROM 3 is selected - so ROM 3 is on only round the call)
			inc b
			xor a
			out (c), a
			dec b
			ld a, #50               ; MMU 0, 1 back
			out (c), a
			inc b
			ld a, (#BA00 + (ld_m0 - ld_tramp))
			out (c), a
			dec b
			ld a, #51
			out (c), a
			inc b
			ld a, (#BA00 + (ld_m1 - ld_tramp))
			out (c), a
			ld hl, #BAB0            ; the system variables' area back
			ld de, #5C00
			ld bc, 124
			ldir
			ld sp, (#BA00 + (ld_sp - ld_tramp))
			ret
ld_bc:		dw 0
ld_de:		dw 0
ld_ix:		dw 0
ld_a:		db 0
ld_l:		dw 0
ld_cy:		db 0
ld_m0:		db 0
ld_m1:		db 0
ld_sp:		dw 0
ld_trampe:
			ASSERT ld_trampe - ld_tramp <= #B0, "Loader: the trampoline must end below #BAB0"


ntc_pgloaded:	db 4		; the pages taken from the start (Loaded n, Option SaveNex, Option Memory Reserve Pages, the program's own: 0 1 2 5): how many, then the pages
			dw 0, 1, 2, 5
ntc_rg581_e:
