arr_lx		equ ntc_bss + 0		; 10 bytes
arr_ly		equ ntc_bss + 10		; 10 bytes
arr_lvx		equ ntc_bss + 20		; 10 bytes
arr_lscr		equ ntc_bss + 30		; 10 bytes
arr_llife		equ ntc_bss + 40		; 10 bytes
